  state.runs[previous] = { id: previous, action: 'memo', status: 'done', started_at: 1791273600, trace: [
    { at: 1791273600, text: 'Simulation : confirmation du site et des profils de l’équipe' },
    { at: 1791273640, text: 'Simulation : préparation des sections du mémo éclair' },
    { at: 1791273680, text: 'Simulation : contrôle des sources et des sections' }
  ] };
