      item.status = 'running'; item.run_id = id;
      var run = state.runs[id] = { id: id, action: key, status: 'running', started_at: Date.now() / 1000, trace: [] };
      event('started', 'Simulation : ' + action.title, key);
      var operationTexts = operationFilms[key] || ['Réutilisation des pièces du dossier fictif', 'Préparation de ' + action.title.toLowerCase(), 'Production du document et des prochaines actions', 'Vérification des informations disponibles et manquantes'];
